LessonsView_tmp_stream<<"\n";
	LessonsView_tmp_stream << "    // ── AI Translation Integration for Lessons ──\n";
	LessonsView_tmp_stream << "    let lessonWs;\n";
	LessonsView_tmp_stream << "    let lessonCameraStream = null;\n";
	LessonsView_tmp_stream << "    let isLessonTranslating = false;\n";
	LessonsView_tmp_stream << "    let lessonIntervalId = null;\n";
	LessonsView_tmp_stream << "    let isLessonWaitingForFrame = false;\n";
	LessonsView_tmp_stream << "    let consecutiveSuccesses = 0;\n";
	LessonsView_tmp_stream << "    \n";
	LessonsView_tmp_stream << "    // Normalize target sign string for robust matching against the backend\n";
	LessonsView_tmp_stream << "    function normalizeTargetSign(str) {\n";
	LessonsView_tmp_stream << "      if (!str) return \"\";\n";
	LessonsView_tmp_stream << "      let normalized = str.replace(/^\\d+\\.\\s*/, '').toLowerCase().trim();\n";
	LessonsView_tmp_stream << "      normalized = normalized.replace(/[.?!…]+$/, '');\n";
	LessonsView_tmp_stream << "      return normalized;\n";
	LessonsView_tmp_stream << "    }\n";
LessonsView_tmp_stream<<"\n";
	LessonsView_tmp_stream << "    function toggleLessonCamera() {\n";
